"""
This module holds the testline configuration and provides functions
to access specific information from the testline configuration.
"""
import functools
from .tools import python_log
import logging


logger = logging.getLogger()


TL_CONFIG = None
BIP_CONFIG = {}


def log_bip_config():
    logger.info(BIP_CONFIG)
    log_string = ''
    for gnb_id in BIP_CONFIG:
        log_string = 'gNodeB {}:\n'.format(gnb_id)
        for key, value in BIP_CONFIG[gnb_id].items():
            log_string += '  {}: {}\n'.format(key, value)
    logger.info(log_string)


def invalidate_cache():
    global TL_CONFIG
    global BIP_CONFIG
    TL_CONFIG = None
    BIP_CONFIG = {}


@python_log
def get_oam_ssh_connection(gnb_id):
    if not TL_CONFIG:
        return {'host': '192.168.255.129',
                'user': 'toor4nsn',
                'password': 'oZPS0POrRieRtu'}

    return {'host': TL_CONFIG.gnbs[gnb_id].cu.oam_ssh_connection_details.addr,
            'user': TL_CONFIG.gnbs[gnb_id].cu.oam_ssh_connection_details.username,
            'password': TL_CONFIG.gnbs[gnb_id].cu.oam_ssh_connection_details.password}


def get_oam_bts_host(gnb_id):
    if not TL_CONFIG:
        return '192.168.255.129'
    return TL_CONFIG.gnbs[gnb_id].cu.oam_http_connection_details.addr


def get_oam_bts_remote_host(gnb_id):
    if not TL_CONFIG:
        return

    test_pc = get_test_pc(gnb_id, node_type='gnb')
    if TL_CONFIG.test_pc.default_ssh_connection_details.addr != test_pc.default_ssh_connection_details.addr:
        return test_pc.default_ssh_connection_details.addr


def check_testline_configuration(tl_config):
    assert len(tl_config.gnbs) > 0, "TL_CONFIG ERROR: There should be at least one gnb defined!"

    for gnb_index, gnb in enumerate(tl_config.gnbs):
        assert len(gnb.dus) > 0, "TL_CONFIG ERROR: GNB {} should have at least one du".format(gnb_index)

        for du_index, du in enumerate(gnb.dus):
            assert len(du.airscale.common_units) > 0, \
                "TL_CONFIG ERROR: GNB {} with DU {} should have at least one common_unit".format(gnb_index, du_index)


@python_log
def get_lmp_connection(gnb_id=0, du_id=0, comu_id=0):
    try:
        lmp_connection = TL_CONFIG.gnbs[gnb_id].dus[du_id].airscale.common_units[comu_id].lmp_connection
    except IndexError:
        raise AssertionError("lmp connection not found! Please check your testline configuration!")
    except AttributeError:
        return {'host': '192.168.255.129',
                'user': 'toor4nsn',
                'password': 'oZPS0POrRieRtu'}

    return {'host': lmp_connection.addr,
            'user': lmp_connection.username,
            'password': lmp_connection.password}


def get_test_pc_for_nodeb(nodeb):
    """
    Determines the test pc by the given nodeb inside of the given testline configuration.
    It is checked in the list of given test pcs, which test pc has a entry in its list of connections
    to the given nodeb. The corresponding test pc is returned. If no test pc was found, the first
    element of the test_pcs list in the testine configuration is returned.

    :param tl: The testlinec configuration
    :param nodeb: The nodeb configuration object in the testline config.
    """
    test_pcs = [test_pc for test_pc in TL_CONFIG.test_pcs for obj in test_pc.connections if obj is nodeb]
    if test_pcs:
        return test_pcs[0]

    return TL_CONFIG.test_pc


def get_test_pc(node_id=0, node_type='gnb'):
    """
    This function determines the test pc in the testline configuration, depening on the given
    node_type and node_id

    :parm tl: The testline configuration
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    """
    if node_type == 'gnb':
        return get_test_pc_for_nodeb(TL_CONFIG.gnbs[node_id])
    elif node_type == 'enb':
        return get_test_pc_for_nodeb(TL_CONFIG.enbs[node_id])

    raise AssertionError("Error in getting node: invalid node type {}".format(node_type))


def configuration(config_name):
    def decorator(function):
        @functools.wraps(function)
        def wrapper(*args, **kwargs):
            if config_name not in BIP_CONFIG:
                BIP_CONFIG[config_name] = function(*args, **kwargs)
            return BIP_CONFIG[config_name]
        return wrapper
    return decorator
